import{_ as o,o as a,c as t,a0 as r}from"./chunks/framework.DRjqbEpm.js";const p=JSON.parse('{"title":"❓ Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),s={name:"en/guide/faq.md"};function i(n,e,l,h,d,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="❓-frequently-asked-questions-faq" tabindex="-1">❓ Frequently Asked Questions (FAQ) <a class="header-anchor" href="#❓-frequently-asked-questions-faq" aria-label="Permalink to &quot;❓ Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Do you have a problem? Look here first! If you cannot find the answer, please report it on <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p><hr><h2 id="🔴-progress-bar-problems" tabindex="-1">🔴 Progress Bar Problems <a class="header-anchor" href="#🔴-progress-bar-problems" aria-label="Permalink to &quot;🔴 Progress Bar Problems&quot;">​</a></h2><h3 id="q-why-do-i-not-see-progress-bars-on-a-video-website" tabindex="-1">Q: Why do I not see progress bars on a video website? <a class="header-anchor" href="#q-why-do-i-not-see-progress-bars-on-a-video-website" aria-label="Permalink to &quot;Q: Why do I not see progress bars on a video website?&quot;">​</a></h3><p><strong>Check these things:</strong></p><ol><li><p><strong>You did not authorize the website.</strong> → Open the Dashboard. Click the <strong>&quot;Authorize &amp; Enable Current Site&quot;</strong> button.</p></li><li><p><strong>V-Train does not know this website.</strong> → If you authorized the website but still see nothing, V-Train needs rules. Use the <a href="./adaptive-engine.html">Adaptive Engine</a> to train it!</p></li><li><p><strong>V-Train is turned off.</strong> → ✅ Make sure the status toggle on the Dashboard says &quot;<strong>🟢 Monitoring</strong>&quot;. It must not be &quot;<strong>Monitoring Off</strong>&quot;.</p></li><li><p><strong>You are watching the video.</strong> → Progress bars only appear on the <strong>video list page</strong>. You will not see them when you are watching the video.</p></li><li><p><strong>You need to refresh the page.</strong> → Press <strong>F5</strong> to reload the website.</p></li></ol><hr><h3 id="q-why-did-some-progress-bars-disappear" tabindex="-1">Q: Why did some progress bars disappear? <a class="header-anchor" href="#q-why-did-some-progress-bars-disappear" aria-label="Permalink to &quot;Q: Why did some progress bars disappear?&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Free Version Limit</p><p>The Free version only remembers <strong>200 videos</strong>. When you watch more than 200, it deletes the oldest ones. If you want to keep all your progress, please upgrade to the <a href="./pro-features.html">Pro Version</a>.</p></div><p>If you have the Pro version, you might have accidentally cleared your data. Please backup your data often!</p><hr><h3 id="q-how-do-i-change-the-color-of-the-progress-bar" tabindex="-1">Q: How do I change the color of the progress bar? <a class="header-anchor" href="#q-how-do-i-change-the-color-of-the-progress-bar" aria-label="Permalink to &quot;Q: How do I change the color of the progress bar?&quot;">​</a></h3><p>Open the Dashboard. Click the colored square next to <strong>&quot;Progress Bar Color&quot;</strong>. You can choose any color you want!</p><hr><h2 id="🖼️-screenshot-problems" tabindex="-1">🖼️ Screenshot Problems <a class="header-anchor" href="#🖼️-screenshot-problems" aria-label="Permalink to &quot;🖼️ Screenshot Problems&quot;">​</a></h2><h3 id="q-why-is-there-a-red-❌-on-the-screenshot-button" tabindex="-1">Q: Why is there a red ❌ on the screenshot button? <a class="header-anchor" href="#q-why-is-there-a-red-❌-on-the-screenshot-button" aria-label="Permalink to &quot;Q: Why is there a red ❌ on the screenshot button?&quot;">​</a></h3><p>V-Train tries many ways to take a picture, but sometimes it fails:</p><div class="warning custom-block"><p class="custom-block-title">Common reasons for screenshot failure</p><ul><li><strong>Cross-origin iframe</strong>: The video is loaded from a different website.</li><li><strong>Strict Security Policies</strong>: The website blocks screenshots.</li><li><strong>Protected Video</strong>: You cannot take pictures of DRM-protected videos.</li></ul></div><p>If a screenshot fails, you can still:</p><ul><li>Save the video to your Bookmark Vault (it will use the website&#39;s original picture).</li><li>Track your viewing progress.</li></ul><hr><h3 id="q-my-screenshot-covers-disappeared-what-happened" tabindex="-1">Q: My screenshot covers disappeared! What happened? <a class="header-anchor" href="#q-my-screenshot-covers-disappeared-what-happened" aria-label="Permalink to &quot;Q: My screenshot covers disappeared! What happened?&quot;">​</a></h3><p>Your screenshots are saved inside your browser. They will disappear if you:</p><ul><li>Uninstall V-Train.</li><li>Clear your browser data (cache and cookies).</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 How to keep them safe?</p><p>Use the <strong>Export Full Backup</strong> button on the Dashboard. Choose the option to include pictures. Your pictures will be saved in the backup ZIP file!</p></div><hr><h2 id="📕-bookmark-vault-problems" tabindex="-1">📕 Bookmark Vault Problems <a class="header-anchor" href="#📕-bookmark-vault-problems" aria-label="Permalink to &quot;📕 Bookmark Vault Problems&quot;">​</a></h2><h3 id="q-why-do-the-pictures-in-the-bookmark-vault-break-after-a-few-days" tabindex="-1">Q: Why do the pictures in the Bookmark Vault break after a few days? <a class="header-anchor" href="#q-why-do-the-pictures-in-the-bookmark-vault-break-after-a-few-days" aria-label="Permalink to &quot;Q: Why do the pictures in the Bookmark Vault break after a few days?&quot;">​</a></h3><p>Many video websites stop you from loading their pictures on other pages. This is a common problem.</p><p>V-Train has a special tool to fix this:</p><blockquote><p>Every time you open the Bookmark Vault, V-Train finds the broken pictures. It tells Chrome to trick the video websites. This makes the pictures load normally.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 How to fix broken pictures</p><ol><li>Close the Bookmark Vault tab.</li><li>Open it again. Wait a few seconds for the tool to work.</li><li>If it is still broken, go to the video page and use the 📸 button to take your own picture. Your own pictures never break!</li></ol></div><hr><h3 id="q-i-deleted-a-bookmark-by-mistake-can-i-get-it-back" tabindex="-1">Q: I deleted a bookmark by mistake. Can I get it back? <a class="header-anchor" href="#q-i-deleted-a-bookmark-by-mistake-can-i-get-it-back" aria-label="Permalink to &quot;Q: I deleted a bookmark by mistake. Can I get it back?&quot;">​</a></h3><p>No, you <strong>cannot get it back</strong> (unless you have a backup). V-Train does not have a &quot;trash bin&quot;. All data lives on your computer.</p><div class="warning custom-block"><p class="custom-block-title">Advice</p><ul><li><strong>Backup</strong> your data before you delete many bookmarks.</li><li>Put important bookmarks in a special folder so you do not delete them.</li></ul></div><hr><h2 id="🔐-passcode-and-privacy-problems" tabindex="-1">🔐 Passcode and Privacy Problems <a class="header-anchor" href="#🔐-passcode-and-privacy-problems" aria-label="Permalink to &quot;🔐 Passcode and Privacy Problems&quot;">​</a></h2><h3 id="q-i-forgot-my-passcode" tabindex="-1">Q: I forgot my passcode! <a class="header-anchor" href="#q-i-forgot-my-passcode" aria-label="Permalink to &quot;Q: I forgot my passcode!&quot;">​</a></h3><p>Read the &quot;I Forgot My Passcode!&quot; section in the <a href="./pro-features.html">Pro Features Guide</a>.</p><p>Quick steps: Click <strong>&quot;Forgot Passcode?&quot;</strong> → Enter your <strong>Pro License Key</strong> → The passcode is removed.</p><hr><h3 id="q-does-v-train-upload-my-private-data" tabindex="-1">Q: Does V-Train upload my private data? <a class="header-anchor" href="#q-does-v-train-upload-my-private-data" aria-label="Permalink to &quot;Q: Does V-Train upload my private data?&quot;">​</a></h3><p><strong>No. Never.</strong> V-Train does not use servers:</p><ul><li>All your viewing history, bookmarks, and rules stay <strong>on your computer</strong>.</li><li>We only check your Pro License Key online. We do not send your personal data.</li><li>V-Train <strong>does not have a database server</strong>.</li></ul><hr><h3 id="q-if-i-uninstall-v-train-do-i-lose-my-data" tabindex="-1">Q: If I uninstall V-Train, do I lose my data? <a class="header-anchor" href="#q-if-i-uninstall-v-train-do-i-lose-my-data" aria-label="Permalink to &quot;Q: If I uninstall V-Train, do I lose my data?&quot;">​</a></h3><p><strong>Yes!</strong> If you remove the extension, Chrome will delete all your data:</p><ul><li>Your history, bookmarks, and screenshots.</li><li>Your settings.</li></ul><div class="danger custom-block"><p class="custom-block-title">⚠️ Backup before uninstalling!</p><p>If you have important data, you must <strong>Export a Full Backup</strong> before you remove V-Train!</p></div><hr><h2 id="🌐-adaptive-engine-problems" tabindex="-1">🌐 Adaptive Engine Problems <a class="header-anchor" href="#🌐-adaptive-engine-problems" aria-label="Permalink to &quot;🌐 Adaptive Engine Problems&quot;">​</a></h2><h3 id="q-i-finished-training-but-there-are-no-progress-bars" tabindex="-1">Q: I finished training, but there are no progress bars? <a class="header-anchor" href="#q-i-finished-training-but-there-are-no-progress-bars" aria-label="Permalink to &quot;Q: I finished training, but there are no progress bars?&quot;">​</a></h3><p>Check these things:</p><ol><li><strong>Did you authorize the website?</strong> Dashboard → Authorize Current Site.</li><li><strong>Did you refresh the page?</strong> Press F5.</li><li><strong>Did the rule save?</strong> Dashboard → Trained Sites. Check if the rule is there.</li><li><strong>Did you select the right box?</strong> You must select the box that holds the picture, not the picture itself.</li></ol><p>If it still does not work, the website link might be difficult. Delete the rule and try again. Try clicking a different part of the link for the Video ID.</p><hr><h3 id="q-my-friend-gave-me-a-vt-rule-serial-number-how-do-i-use-it" tabindex="-1">Q: My friend gave me a VT-RULE serial number. How do I use it? <a class="header-anchor" href="#q-my-friend-gave-me-a-vt-rule-serial-number-how-do-i-use-it" aria-label="Permalink to &quot;Q: My friend gave me a VT-RULE serial number. How do I use it?&quot;">​</a></h3><ol><li>Open the Dashboard.</li><li>Click the <strong>&quot;Trained Sites (Rules)&quot;</strong> button.</li><li>Find the &quot;Import Rule&quot; box.</li><li>Paste the <code>VT-RULE-Z...</code> number and click confirm.</li><li>The rule works immediately!</li></ol><hr><h2 id="⚡-speed-problems" tabindex="-1">⚡ Speed Problems <a class="header-anchor" href="#⚡-speed-problems" aria-label="Permalink to &quot;⚡ Speed Problems&quot;">​</a></h2><h3 id="q-will-v-train-make-my-computer-slow" tabindex="-1">Q: Will V-Train make my computer slow? <a class="header-anchor" href="#q-will-v-train-make-my-computer-slow" aria-label="Permalink to &quot;Q: Will V-Train make my computer slow?&quot;">​</a></h3><p>No. V-Train is designed to be very fast:</p><ul><li>It only checks videos you can see on the screen.</li><li>It pauses when nothing is happening.</li><li>It uses very little computer power.</li></ul><p>You will not notice it running.</p><hr><h3 id="q-i-have-many-bookmark-vault-tabs-open-will-they-break" tabindex="-1">Q: I have many Bookmark Vault tabs open. Will they break? <a class="header-anchor" href="#q-i-have-many-bookmark-vault-tabs-open-will-they-break" aria-label="Permalink to &quot;Q: I have many Bookmark Vault tabs open. Will they break?&quot;">​</a></h3><p>No! V-Train syncs them all automatically. If you add a bookmark in one tab, the other tabs will update immediately.</p><hr><h2 id="🔔-incognito-mode-problems" tabindex="-1">🔔 Incognito Mode Problems <a class="header-anchor" href="#🔔-incognito-mode-problems" aria-label="Permalink to &quot;🔔 Incognito Mode Problems&quot;">​</a></h2><h3 id="q-can-i-use-v-train-in-incognito-mode" tabindex="-1">Q: Can I use V-Train in Incognito Mode? <a class="header-anchor" href="#q-can-i-use-v-train-in-incognito-mode" aria-label="Permalink to &quot;Q: Can I use V-Train in Incognito Mode?&quot;">​</a></h3><p>Yes, but you must turn it on:</p><ol><li>Type <code>chrome://extensions/</code> in Chrome.</li><li>Find V-Train and click <strong>&quot;Details&quot;</strong>.</li><li>Turn on the <strong>&quot;Allow in Incognito&quot;</strong> switch.</li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>V-Train shares data between normal mode and incognito mode. Your history in incognito mode will be saved with your normal history.</p></div><hr><h2 id="💬-still-need-help" tabindex="-1">💬 Still need help? <a class="header-anchor" href="#💬-still-need-help" aria-label="Permalink to &quot;💬 Still need help?&quot;">​</a></h2><ol><li>Search on <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to see if someone has the same problem.</li><li>If not, click <strong>&quot;New Issue&quot;</strong> and tell us: <ul><li>Your Chrome version.</li><li>Your V-Train version.</li><li>The website that has the problem.</li><li>What went wrong.</li></ul></li></ol>',78)])])}const b=o(s,[["render",i]]);export{p as __pageData,b as default};
